<?php require "../config/auth.php";require "../config/database.php";if($_SERVER["REQUEST_METHOD"]==="POST"){$vals=[];foreach(["nama", "tanggal", "lokasi", "deskripsi", "status", "poster"] as $c)$vals[]=$_POST[$c]??"";$pdo->prepare("INSERT INTO kegiatan (nama,tanggal,lokasi,deskripsi,status,poster) VALUES (?,?,?,?,?,?)")->execute($vals);header("Location:kegiatan.php");exit;}if(isset($_GET["delete"])){$pdo->prepare("DELETE FROM kegiatan WHERE id=?")->execute([(int)$_GET["delete"]]);header("Location:kegiatan.php");exit;}$rows=$pdo->query("SELECT * FROM kegiatan ORDER BY id DESC")->fetchAll();?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kegiatan | Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><div class="d-flex justify-content-between"><h2>Kegiatan</h2><a href="index.php">Dashboard</a></div><div class="card p-4 my-4"><form method="post" class="row g-3"><div class="col-md-6"><label class="form-label">Nama</label><input name="nama" class="form-control"></div><div class="col-md-6"><label class="form-label">Tanggal</label><input name="tanggal" class="form-control"></div><div class="col-md-6"><label class="form-label">Lokasi</label><input name="lokasi" class="form-control"></div><div class="col-md-6"><label class="form-label">Deskripsi</label><input name="deskripsi" class="form-control"></div><div class="col-md-6"><label class="form-label">Status</label><input name="status" class="form-control"></div><div class="col-md-6"><label class="form-label">Poster</label><input name="poster" class="form-control"></div><div class="col-12"><button class="btn btn-primary">Tambah</button></div></form></div><div class="table-responsive"><table class="table table-striped"><thead><tr><th>ID</th><th>nama</th><th>tanggal</th><th>lokasi</th><th>deskripsi</th><th>status</th><th>poster</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r["id"]?></td><td><?=e($r["nama"])?></td><td><?=e($r["tanggal"])?></td><td><?=e($r["lokasi"])?></td><td><?=e($r["deskripsi"])?></td><td><?=e($r["status"])?></td><td><?=e($r["poster"])?></td><td><a class="btn btn-sm btn-danger" href="?delete=<?=$r["id"]?>" onclick="return confirm('Hapus data?')">Hapus</a></td></tr><?php endforeach;?></tbody></table></div></div></body></html>